    "css": ".absolute{position:absolute}.relative{position:relative}.inset-y-0{top:0px;bottom:0px}.left-3{left:0.75rem}.my-auto{margin-top:auto;margin-bottom:auto}.mt-2{margin-top:0.5rem}.flex{display:flex}.h-6{height:1.5rem}.h-full{height:100%}.w-full{width:100%}.max-w-\\[350px\\]{max-width:350px}.max-w-xs{max-width:20rem}.appearance-none{-webkit-appearance:none;appearance:none}.items-center{align-items:center}.rounded-lg{border-radius:0.5rem}.border{border-width:1px}.border-r{border-right-width:1px}.bg-transparent{background-color:transparent}.bg-white{--tw-bg-opacity:1;background-color:rgb(255 255 255 / var(--tw-bg-opacity))}.p-4{padding:1rem}.py-2{padding-top:0.5rem;padding-bottom:0.5rem}.pl-\\[4\\.5rem\\]{padding-left:4.5rem}.pr-2{padding-right:0.5rem}.pr-3{padding-right:0.75rem}.text-sm{font-size:0.875rem;line-height:1.25rem}.text-gray-500{--tw-text-opacity:1;color:rgb(107 114 128 / var(--tw-text-opacity))}.text-gray-600{--tw-text-opacity:1;color:rgb(75 85 99 / var(--tw-text-opacity))}.shadow-sm{--tw-shadow:0 1px 2px 0 rgb(0 0 0 / 0.05);--tw-shadow-colored:0 1px 2px 0 var(--tw-shadow-color);box-shadow:var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)}.outline-none{outline:2px solid transparent;outline-offset:2px}.focus\\:border-slate-600:focus{--tw-border-opacity:1;border-color:rgb(71 85 105 / var(--tw-border-opacity))}"
