    "html": "<div class=\"input-container\">\n<input class=\"input\" name=\"text\" type=\"text\">\n<label class=\"label\" for=\"input\">Enter Your Name</label>\n<div class=\"topline\"></div>\n<div class=\"underline\"></div>\n</div>",
    "css": ".input-container {\n  position: relative;\n}\n\n.input {\n  padding: 10px;\n  height: 40px;\n  border: 2px solid #0B2447;\n  border-top: none;\n  font-size: 16px;\n  background: transparent;\n  outline: none;\n  box-shadow: 7px 7px 0px 0px #0B2447;\n  transition: all 0.5s;\n}\n\n.input:focus {\n  box-shadow: none;\n  transition: all 0.5s;\n}\n\n.label {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  color: #0B2447;\n  transition: all 0.5s;\n  transform: scale(0);\n  z-index: -1;\n}\n\n.input-container .topline {\n  position: absolute;\n  content: \"\";\n  background-color: #0B2447;\n  width: 0%;\n  height: 2px;\n  right: 0;\n  top: 0;\n  transition: all 0.5s;\n}\n\n.input-container input[type=\"text\"]:focus ~ .topline {\n  width: 35%;\n  transition: all 0.5s;\n}\n\n.input-container .underline {\n  position: absolute;\n  content: \"\";\n  background-color: #0B2447;\n  width: 0%;\n  height: 2px;\n  right: 0;\n  bottom: 0;\n  transition: all 0.5s;\n}\n\n.input-container input[type=\"text\"]:focus ~ .underline {\n  width: 100%;\n  transition: all 0.5s;\n}\n\n.input-container input[type=\"text\"]:focus ~ .label {\n  top: -10px;\n  transform: scale(1);\n  transition: all 0.5s;\n}"
