    "css": ".absolute{position:absolute}.relative{position:relative}.left-0{left:0px}.top-1{top:0.25rem}.flex{display:flex}.cursor-text{cursor:text}.items-center{align-items:center}.justify-center{justify-content:center}.border-b{border-bottom-width:1px}.border-gray-300{--tw-border-opacity:1;border-color:rgb(209 213 219 / var(--tw-border-opacity))}.bg-inherit{background-color:inherit}.py-1{padding-top:0.25rem;padding-bottom:0.25rem}.transition-all{transition-property:all;transition-timing-function:cubic-bezier(0.4, 0, 0.2, 1);transition-duration:150ms}.transition-colors{transition-property:color, background-color, border-color, fill, stroke, -webkit-text-decoration-color;transition-property:color, background-color, border-color, text-decoration-color, fill, stroke;transition-property:color, background-color, border-color, text-decoration-color, fill, stroke, -webkit-text-decoration-color;transition-timing-function:cubic-bezier(0.4, 0, 0.2, 1);transition-duration:150ms}.focus\\:border-b-2:focus{border-bottom-width:2px}.focus\\:border-blue-700:focus{--tw-border-opacity:1;border-color:rgb(29 78 216 / var(--tw-border-opacity))}.focus\\:outline-none:focus{outline:2px solid transparent;outline-offset:2px}.peer:focus ~ .peer-focus\\:-top-4{top:-1rem}.peer:focus ~ .peer-focus\\:text-xs{font-size:0.75rem;line-height:1rem}.peer:focus ~ .peer-focus\\:text-blue-700{--tw-text-opacity:1;color:rgb(29 78 216 / var(--tw-text-opacity))}"
