    "html": "<div class=\"box-input\">\n  <div class=\"border\">\n    <input type=\"text\" name=\"text\" class=\"input\" placeholder=\"Name\">\n  </div>\n</div>\n",
    "css": ".box-input {\n  position: relative;\n}\n\n.border {\n  background-image: linear-gradient(to right bottom, #e300ff, #ff00aa, #ff5956, #ffb900, #fffe00);\n  box-shadow: -25px -10px 30px -5px rgba(225, 0, 255, 0.5),\n    25px -10px 30px -5px rgba(255, 0, 212, 0.5),\n    25px 10px 30px -5px rgba(255, 174, 0, 0.5),\n    -25px 10px 30px -5px rgba(255, 230, 0, 0.5);\n  padding: 4px;\n}\n\n.input {\n  background-color: #212121;\n  max-width: 250px;\n  height: 40px;\n  padding: 0 19px 0 10px;\n  font-size: 1.1em;\n  position: relative;\n  border: none;\n  color: white;\n  outline: 0;\n  overflow: hidden;\n}\n\n.box-input::after,\n.box-input::before {\n  content: \"\";\n  width: 130px;\n  height: 30px;\n  position: absolute;\n  z-index: -1;\n}\n\n.box-input::after {\n  bottom: 0;\n  right: 0;\n}\n\n.box-input::before {\n  top: 0;\n  left: 0;\n}\n\n.input::placeholder {\n  transition: all 0.5s ease-in, transform 0.2s ease-in 0.6s;\n}\n\n.input:focus::placeholder {\n  padding-left: 165px;\n  transform: translateY(-50px);\n}\n"
