    "html": "<div class=\"PB-range-slider-div\">\n<input type=\"range\" min=\"0\" max=\"100\" value=\"50\" class=\"PB-range-slider\" id=\"myRange\">\n<p class=\"PB-range-slidervalue\">50px</p>\n</div>",
    "css": ".PB-range-slider {\n  -webkit-appearance: none;\n  width: 100%;\n  height: 4px;\n  border-radius: 5px;\n  background: #D5DBE1;\n  outline: none;\n  opacity: 0.7;\n  -webkit-transition: .2s;\n  transition: opacity .2s;\n}\n\n.PB-range-slider::-webkit-slider-thumb {\n  -webkit-appearance: none;\n  appearance: none;\n  width: 15px;\n  height: 15px;\n  border-radius: 50%;\n  background-color: #000000;\n  cursor: pointer;\n  transition: 0.3s ease-in-out;\n}\n\n.PB-range-slider::-webkit-slider-thumb:hover {\n  box-shadow: 0px 0px 0px 8px rgba(0, 0, 0, 0.16);\n  transition: 0.3s ease-in-out;\n}\n\n.PB-range-slider::-moz-range-thumb {\n  width: 15px;\n  height: 15px;\n  border-radius: 50%;\n  background-color: #000000;\n  cursor: pointer;\n}\n\n.PB-range-slider-div {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 1rem;\n  padding: 1rem;\n  border-radius: 6px;\n  border: 1px solid #C6CACE;\n  box-shadow: 0px 1px 2px 0px #1F1E241F;\n}\n\n.PB-range-slidervalue {\n  font-weight: 600;\n}"
