    "html": "<div class=\"flex h-[34px] text-[14px] text-white/60\">\n  <input\n    class=\"input w-[200px] bg-[#09090b] text-[#f4f4f5] px-3 py-1 rounded-l-lg border border-white/10 focus:outline-none focus:ring-2 focus:ring-gray-700 focus:ring-offset-2 focus:ring-offset-[#09090b] transition-all duration-150 ease-in-out\"\n    name=\"text\"\n    type=\"text\"\n    placeholder=\"Email\"\n  />\n  <button\n    class=\"text-[#f4f4f5] px-3 py-1 rounded-r-lg border-y border-r border-r-white/10 border-y-white/10 hover:bg-zinc-800/40 transition-all duration-150 easy-in-out\"\n  >\n    Send\n  </button>\n</div>\n",
