    "html": "<div class=\"info-panels\">\n  <div class=\"input-color-group-one\">\n    <input\n      placeholder=\"255, 255, 255, 0.5\"\n      required=\"\"\n      type=\"text\"\n      id=\"input-text\"\n      name=\"text\"\n      autocomplete=\"on\"\n      class=\"input-color\"\n    />\n    <label class=\"color-label\">RGBA</label>\n    <button class=\"btn-copy\">\n      <svg\n        viewBox=\"0 0 24 24\"\n        xmlns=\"http://www.w3.org/2000/svg\"\n        id=\"icon-btn-copy\"\n        class=\"svgs\"\n      >\n        <path\n          d=\"M15.98,13.96h-4.74c-.13,0-.24-.11-.24-.24V7.07c0-.13,.11-.24,.24-.24h4.74c.13,0,.24,.11,.24,.24v6.64c0,.13-.11,.24-.24,.24Zm-6.77-7.72V14.55c0,.66,.53,1.19,1.19,1.19h6.41c.66,0,1.19-.53,1.19-1.19V6.24c0-.66-.53-1.19-1.19-1.19h-6.41c-.66,0-1.19,.53-1.19,1.19Z\"\n        ></path>\n        <path\n          d=\"M15.68,18.95H7.19c-.66,0-1.19-.53-1.19-1.19V7.37c0-.49,.4-.89,.89-.89s.89,.4,.89,.89v9.57c0,.13,.1,.23,.23,.23h7.67c.49,0,.89,.4,.89,.89s-.4,.89-.89,.89Z\"\n        ></path>\n      </svg>\n    </button>\n  </div>\n</div>\n",
    "css": "/* Import Overpass Mono from Google Fonts */\n@import url(\"s://fonts.googleapis.com/css2?family=Overpass+Mono:wght@400;700&display=swap\");\n\n.input-color-group-one {\n  position: relative;\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.input-color {\n  max-width: 230px;\n  min-width: 150px;\n  border: 2px solid var(--color-border);\n  border-radius: 0px;\n  background: var(--color-bg);\n  color: var(--color-input);\n  padding: 16px;\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.input-color:focus {\n  color: var(--color-input);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.input-color:valid {\n  color: var(--color-input);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.input-color:placeholder {\n  color: var(--color-border);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.color-label {\n  position: absolute;\n  display: flex;\n  justify-content: center;\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n.input-color {\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.info-panels {\n  --color-icon: solid var;\n  --color-input: #000000;\n  --color-border: #1648c7;\n  --color-border-hover: 2px solid var;\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.input-color {\n  max-width: 230px;\n  min-width: 150px;\n  border: 2px solid var(--color-border);\n  border-radius: 0px;\n  background: #fff;\n  font-size: 12px;\n  text-align: center;\n}\n\n.input-color:focus {\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  color: var(--color-input);\n}\n\n.input-color:valid {\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  color: var(--color-input);\n}\n\n.input-color:-webkit-input-placeholder {\n  color: var(--color-input);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n\n  font-size: 12px;\n}\n\n.input-color:-moz-input-placeholder {\n  color: var(--color-input);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n}\n\n.input-color::-ms-input-placeholder {\n  color: var(--color-input);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n}\n\n.input-color:focus::-webkit-input-placeholder,\n.input-color:valid::-webkit-input-placeholder {\n  opacity: var(--input-focus-opacity);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n}\n\n.input-color:focus::-moz-input-placeholder,\n.input-color:valid::-moz-input-placeholder {\n  opacity: var(--input-focus-opacity);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n}\n\n.input-color:focus::-ms-input-placeholder,\n.input-color:valid::-ms-input-placeholder {\n  opacity: var(--input-focus-opacity);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n}\n\n.color-label {\n  position: absolute;\n  display: inline-flex;\n  justify-content: center;\n  align-items: center;\n  color: var(--color-border);\n  font-family: \"Overpass Mono\", monospace;\n  text-transform: uppercase;\n  letter-spacing: 0.04em; /* minimal spacing */\n  font-size: 12px;\n  font-weight: 600;\n  background-color: #fff;\n  padding: 0 5px;\n  border: 2px solid var(--color-border);\n  border-radius: 0px;\n  top: -11.5px;\n  left: 25px;\n  cursor: crosshair;\n  backdrop-filter: blur(10px);\n}\n\n.btn-copy {\n  position: absolute;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  width: 24px;\n  height: 24px;\n  border: 2px solid var(--color-border);\n  border-radius: 50px;\n  top: -11.5px;\n  right: 25px;\n  background-color: #fff;\n  cursor: crosshair;\n  backdrop-filter: blur(10px);\n  transition: var(--all-transition);\n}\n\n.btn-copy:hover {\n  background-color: var(--color-border);\n  transform: scale(1.1);\n}\n\n.btn-copy:active {\n  transform: scale(1.1);\n}\n\n.input-color:focus ~ .btn-copy {\n  border: 2px solid var(--color-border);\n}\n\n.input-color:valid .input-color:focus ~ .btn-copy {\n  border: 2px solid var(--color-border);\n}\n\n.input-color:focus ~ .btn-copy:hover {\n  background-color: var(--color-border-hover);\n}\n\n#icon-btn-copy {\n  fill: var(--color-border);\n}\n\n.btn-copy:hover #icon-btn-copy {\n  fill: var(--color-icon);\n}\n\n.input-color:focus ~ .btn-copy #icon-btn-copy {\n  fill: var(--color-border-hover);\n}\n\n.input-color:focus ~ .btn-copy:hover #icon-btn-copy,\n.input-color:valid ~ .btn-copy:hover #icon-btn-copy {\n  fill: var(--color-icon);\n}\n"
