    "css": ".input-div {\n  position: relative;\n  width: 100px;\n  height: 100px;\n  border-radius: 50%;\n  border: 2px solid rgb(1, 235, 252);\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  overflow: hidden;\n  box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);\n  animation: flicker 2s linear infinite;\n}\n\n.icon {\n  color: rgb(1, 235, 252);\n  font-size: 2rem;\n  cursor: pointer;\n  animation: iconflicker 2s linear infinite;\n}\n\n.input {\n  position: absolute;\n  opacity: 0;\n  width: 100%;\n  height: 100%;\n  cursor: pointer !important;\n}\n\n@keyframes flicker {\n  0% {\n    border: 2px solid rgb(1, 235, 252);\n    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);\n  }\n\n  5% {\n    border: none;\n    box-shadow: none;\n  }\n\n  10% {\n    border: 2px solid rgb(1, 235, 252);\n    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);\n  }\n\n  25% {\n    border: none;\n    box-shadow: none;\n  }\n\n  30% {\n    border: 2px solid rgb(1, 235, 252);\n    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);\n  }\n\n  100% {\n    border: 2px solid rgb(1, 235, 252);\n    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);\n  }\n}\n\n@keyframes iconflicker {\n  0% {\n    opacity: 1;\n  }\n\n  5% {\n    opacity: 0.2;\n  }\n\n  10% {\n    opacity: 1;\n  }\n\n  25% {\n    opacity: 0.2;\n  }\n\n  30% {\n    opacity: 1;\n  }\n\n  100% {\n    opacity: 1;\n  }\n}"
