    "createdAt": "2026-09-10T23:14:01.727Z",
    "html": "<div class=\"card\">\n  <div class=\"terminal\">\n    <div class=\"terminal-header\">\n      <span class=\"terminal-title\">\n        <svg\n          class=\"terminal-icon\"\n          width=\"16\"\n          height=\"16\"\n          viewBox=\"0 0 24 24\"\n          fill=\"none\"\n          stroke=\"currentColor\"\n          stroke-width=\"2\"\n          stroke-linecap=\"round\"\n          stroke-linejoin=\"round\"\n        >\n          <path d=\"M4 17l6-6-6-6M12 19h8\"></path>\n        </svg>\n        Terminal\n      </span>\n    </div>\n    <div class=\"terminal-body\">\n      <div class=\"command-line\">\n        <span class=\"prompt\">password:</span>\n        <div class=\"input-wrapper\">\n          <input\n            type=\"password\"\n            class=\"input-field\"\n            placeholder=\"Enter password\"\n          />\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n",
    "css": ".card {\n  background-color: rgba(217, 217, 217, 0.18);\n  backdrop-filter: blur(8px);\n  border-radius: 12px;\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\n  overflow: hidden;\n  width: 400px;\n}\n\n.terminal-header {\n  background-color: #202425;\n  padding: 10px 15px;\n  display: flex;\n  align-items: center;\n}\n\n.terminal-title {\n  color: #ffffff;\n  font-size: 14px;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.terminal-icon {\n  color: #006adc;\n}\n\n.terminal-body {\n  background-color: #202425;\n  color: #ffffff;\n  padding: 15px;\n  font-family: \"Courier New\", Courier, monospace;\n}\n\n.command-line {\n  display: flex;\n  align-items: center;\n}\n\n.prompt {\n  color: #ffffff;\n  margin-right: 10px;\n}\n\n.input-wrapper {\n  position: relative;\n  flex-grow: 1;\n}\n\n.input-field {\n  background-color: transparent;\n  border: none;\n  color: #006adc;\n  font-family: inherit;\n  font-size: 14px;\n  outline: none;\n  width: 100%;\n  padding-right: 10px;\n}\n\n.input-field::placeholder {\n  color: rgba(255, 255, 255, 0.5);\n}\n\n.input-wrapper::after {\n  content: \"\";\n  position: absolute;\n  right: 0;\n  top: 50%;\n  transform: translateY(-50%);\n  width: 8px;\n  height: 15px;\n  background-color: #ffffff;\n  animation: blink 1s step-end infinite;\n}\n\n@keyframes blink {\n  0%,\n  100% {\n    opacity: 1;\n  }\n  50% {\n    opacity: 0;\n  }\n}\n"
