    "html": "<div class=\"form__group_one\">\n  <input\n    type=\"text\"\n    class=\"form__group_oneform__field w-100\"\n    placeholder=\"Input text\"\n  />\n  <label for=\"name\" class=\"form__group_oneform__label\"> Input text </label>\n</div>\n",
    "css": ".form__group_one {\n  position: relative;\n}\n\n.form__group_oneform__field {\n  border: 1px solid silver !important;\n  border-radius: 5px;\n  box-sizing: border-box;\n  color: #0b2447;\n  height: 40px;\n  padding: 0rem 15px;\n  box-shadow: 5px 5px 0 0;\n}\n\n.form__group_oneform__field::placeholder {\n  color: transparent;\n}\n\n.form__group_oneform__field:placeholder-shown ~ .form__group_oneform__label {\n  top: 10px;\n  border-right: none;\n  border-left: none;\n}\n\n.form__group_oneform__label {\n  background-color: white;\n  border-left: 1px solid silver;\n  border-right: 1px solid silver;\n  color: #9b9b9b;\n  display: block;\n  font-size: 0.9em;\n  margin-left: 10px;\n  padding: 0 10px;\n  pointer-events: none;\n  position: absolute;\n  top: -10px;\n  transition: 0.2s;\n}\n\n.form__group_oneform__field:focus {\n  border: 1px solid #0b2447 !important;\n  outline: none;\n  box-shadow: none;\n  transform: matrix3d();\n  animation-duration: 1;\n}\n\n.form__group_oneform__field:focus ~ .form__group_oneform__label {\n  background-color: white;\n  border-right: 1px solid #0b2447;\n  border-left: 1px solid #0b2447;\n  color: #0b2447;\n  font-size: 0.9em;\n  margin-left: 10px;\n  padding: 0 10px;\n  position: absolute;\n  top: -10px;\n  transition: 0.2s;\n}\n"
